import axios from "axios";
import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useParams } from "react-router-dom";

export default function EditCustomer() {
    const [customer, setCustomer] = useState({})
    const navigate = useNavigate();
    const {id} = useParams();

    useEffect(() => {
        axios
        .get(`http://localhost:5000/api/v1/customers/${id}`)
        .then((res) => {
            setCustomer(res.data)
        })
        .catch((err) => console.log(err))
    }, [id])

    const updateCustomer = async() => {
        try{
            await axios.put(
                `http://localhost:5000/api/v1/customers/${id}`,
            customer
            );
            alert("Customer Update Successfully")
            navigate("/customer")
        } catch(err) {
            console.log(err)
        }
    }
    return (
        <>
        <div className="container mt-5">
            <div className="card  shadow p-4">
                <h2 className="text-center mb-4">
                    Edit Customer
                </h2>

                <input
    type="text"
    className="form-control"
    value={customer.name || ""}
    onChange={(e) =>
        setCustomer({ ...customer, name: e.target.value })
    }
/>
 <br/><br/>
<input type="text" className="form-control" value={customer.email || ""} onChange={(e) => setCustomer({...customer, name:e.target.value})} />
<br/><br/>
<input type="text" className="form-control" value={customer.phone || ""} onChange={(e) => setCustomer({...customer, name:e.target.value})} />
<br/><br/>
<input type="text" className="form-control" value={customer.city || ""} onChange={(e) => setCustomer({...customer, name:e.target.value})} />
}
            </div>
        </div>
        </>
    )
}
